namespace sv_e8083a54f3d3475a8c26d772c8f407c0.Services;

public record Product(int Id, string Name, decimal Price, string Category, double Rating, bool InStock, string ImageUrl);
public record ProductFilter(List<string>? Categories, decimal? MinPrice, decimal? MaxPrice, bool InStockOnly);
public record PagedResult<T>(List<T> Items, int TotalCount, int Page, int PageSize);

public interface IProductService
{
    Task<PagedResult<Product>> SearchAsync(ProductFilter filter, string sortBy, int page, int pageSize);
    Task<List<string>> GetCategoriesAsync();
}

@using sv_e8083a54f3d3475a8c26d772c8f407c0.Services

<div class="product-card" @onclick="HandleCardClick">
    <div class="product-image" role="img" aria-label="@Product.Name">
        @Product.Name
    </div>
    <div class="product-info">
        <h3 class="product-name">@Product.Name</h3>
        <p class="product-price">@Product.Price.ToString("C")</p>
        <div class="product-rating" aria-label="@($"Rating: {RatingValue} out of 5")">
            @RatingDisplay
        </div>
        @if (!Product.InStock)
        {
            <span class="badge-out-of-stock">Out of Stock</span>
        }
        <button class="btn-add-to-cart"
                disabled="@(!Product.InStock)"
                @onclick="HandleAddToCart"
                @onclick:stopPropagation="true">
            Add to Cart
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Product Product { get; set; } = default!;

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }

    private int RatingValue => (int)Math.Round(Product.Rating);

    private string RatingDisplay
    {
        get
        {
            var filled = RatingValue;
            var empty = 5 - filled;
            return new string('★', filled) + new string('☆', empty);
        }
    }

    private async Task HandleCardClick()
    {
        await OnProductSelected.InvokeAsync(Product);
    }

    private async Task HandleAddToCart()
    {
        await OnAddToCart.InvokeAsync(Product);
    }
}

@using sv_e8083a54f3d3475a8c26d772c8f407c0.Services

@if (Loading)
{
    <div class="catalog-loading">
        <p>Loading products...</p>
    </div>
}
else if (ErrorMessage is not null)
{
    <div class="catalog-error">
        <p>@ErrorMessage</p>
    </div>
}
else if (Products.Count == 0)
{
    <div class="catalog-empty">
        <p>No products found. Try adjusting your filters.</p>
    </div>
}
else
{
    <div class="product-grid">
        @foreach (var product in Products)
        {
            <ProductCard Product="product"
                         OnProductSelected="OnProductSelected"
                         OnAddToCart="OnAddToCart" />
        }
    </div>
}

@code {
    [Parameter]
    public List<Product> Products { get; set; } = [];

    [Parameter]
    public bool Loading { get; set; }

    [Parameter]
    public string? ErrorMessage { get; set; }

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }
}

@page "/catalog"
@using sv_e8083a54f3d3475a8c26d772c8f407c0.Services
@inject IProductService ProductService
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<div class="catalog-layout">
    <CatalogSidebar Categories="categories"
                    OnFilterApplied="HandleFilterApplied"
                    OnFilterCleared="HandleFilterCleared" />

    <div class="catalog-main">
        <CatalogToolbar CurrentSort="@currentSort"
                        TotalCount="totalCount"
                        Page="currentPage"
                        PageSize="pageSize"
                        OnSortChanged="HandleSortChanged" />

        <ProductGrid Products="products"
                     Loading="loading"
                     ErrorMessage="@errorMessage"
                     OnProductSelected="HandleProductSelected"
                     OnAddToCart="HandleAddToCart" />

        @if (!loading && errorMessage is null && products.Count > 0)
        {
            <CatalogPagination CurrentPage="currentPage"
                               TotalPages="totalPages"
                               OnPageChanged="HandlePageChanged" />
        }
    </div>
</div>

@code {
    private List<Product> products = [];
    private List<string> categories = [];
    private int currentPage = 1;
    private int pageSize = 12;
    private int totalCount;
    private int totalPages;
    private string currentSort = "price_asc";
    private bool loading = true;
    private string? errorMessage;

    private ProductFilter currentFilter = new(null, null, null, false);

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    protected override async Task OnInitializedAsync()
    {
        try
        {
            var categoriesTask = ProductService.GetCategoriesAsync();
            var searchTask = LoadProducts();
            categories = await categoriesTask;
            await searchTask;
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load catalog: {ex.Message}";
            loading = false;
        }
    }

    private async Task LoadProducts()
    {
        loading = true;
        errorMessage = null;

        try
        {
            var result = await ProductService.SearchAsync(currentFilter, currentSort, currentPage, pageSize);
            products = result.Items;
            totalCount = result.TotalCount;
            totalPages = (int)Math.Ceiling((double)result.TotalCount / pageSize);
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load products: {ex.Message}";
            products = [];
        }
        finally
        {
            loading = false;
        }
    }

    private async Task HandleFilterApplied(CatalogSidebar.ProductFilterState filterState)
    {
        currentFilter = new ProductFilter(
            filterState.Categories,
            filterState.MinPrice,
            filterState.MaxPrice,
            filterState.InStockOnly);
        currentPage = 1;
        await LoadProducts();
    }

    private async Task HandleFilterCleared()
    {
        currentFilter = new ProductFilter(null, null, null, false);
        currentPage = 1;
        await LoadProducts();
    }

    private async Task HandleSortChanged(string sort)
    {
        currentSort = sort;
        currentPage = 1;
        await LoadProducts();
    }

    private async Task HandlePageChanged(int page)
    {
        currentPage = page;
        await LoadProducts();
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private Task HandleAddToCart(Product product)
    {
        // Placeholder for add-to-cart logic
        return Task.CompletedTask;
    }
}

