{"path": "/tmp/sv-e8083a54f3d3475a8c26d772c8f407c0/Components/Pages/Catalog/CatalogSidebar.razor", "file_text": "<div class="catalog-sidebar">
    <h2>Filters</h2>

    <div class="filter-section">
        <h3>Category</h3>
        @foreach (var category in Categories)
        {
            <label class="filter-checkbox">
                <input type="checkbox"
                       checked="@IsSelected(category)"
                       @onchange="() => ToggleCategory(category)" />
                @category
            </label>
        }
    </div>

    <div class="filter-section">
        <h3>Price Range</h3>
        <label>
            Min:
            <input type="number" min="0" step="0.01"
                   value="@MinPrice"
                   @onchange="e => MinPrice = ParseDecimal(e.Value)" />
        </label>
        <label>
            Max:
            <input type="number" min="0" step="0.01"
                   value="@MaxPrice"
                   @onchange="e => MaxPrice = ParseDecimal(e.Value)" />
        </label>
    </div>

    <div class="filter-section">
        <label class="filter-checkbox">
            <input type="checkbox"
                   checked="@InStockOnly"
                   @onchange="e => InStockOnly = (bool)(e.Value ?? false)" />
            In Stock Only
        </label>
    </div>

    <div class="filter-actions">
        <button class="btn-apply" @onclick="ApplyFilters">Apply Filters</button>
        <button class="btn-clear" @onclick="ClearFilters">Clear Filters</button>
    </div>
</div>

@code {
    [Parameter]
    public List<string> Categories { get; set; } = [];

    [Parameter]
    public EventCallback<ProductFilterState> OnFilterApplied { get; set; }

    [Parameter]
    public EventCallback OnFilterCleared { get; set; }

    private List<string> SelectedCategories { get; set; } = [];
    private decimal? MinPrice { get; set; }
    private decimal? MaxPrice { get; set; }
    private bool InStockOnly { get; set; }

    private bool IsSelected(string category) => SelectedCategories.Contains(category);

    private void ToggleCategory(string category)
    {
        if (SelectedCategories.Contains(category))
            SelectedCategories.Remove(category);
        else
            SelectedCategories.Add(category);
    }

    private static decimal? ParseDecimal(object? value)
    {
        if (value is null || string.IsNullOrWhiteSpace(value.ToString()))
            return null;
        return decimal.TryParse(value.ToString(), out var result) ? result : null;
    }

    private async Task ApplyFilters()
    {
        var state = new ProductFilterState(
            SelectedCategories.Count > 0 ? new List<string>(SelectedCategories) : null,
            MinPrice,
            MaxPrice,
            InStockOnly);
        await OnFilterApplied.InvokeAsync(state);
    }

    private async Task ClearFilters()
    {
        SelectedCategories.Clear();
        MinPrice = null;
        MaxPrice = null;
        InStockOnly = false;
        await OnFilterCleared.InvokeAsync();
    }

    public record ProductFilterState(List<string>? Categories, decimal? MinPrice, decimal? MaxPrice, bool InStockOnly);
}
"}

