@code {
    private List<Product> products = [];
    private List<string> categories = [];
    private int currentPage = 1;
    private int pageSize = 12;
    private int totalCount;
    private int totalPages;
    private string currentSort = "price_asc";
    private bool loading = true;
    private string? errorMessage;

    private ProductFilter currentFilter = new(null, null, null, false);

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    protected override async Task OnInitializedAsync()
    {
        try
        {
            var categoriesTask = ProductService.GetCategoriesAsync();
            var searchTask = LoadProducts();
            categories = await categoriesTask;
            await searchTask;
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load catalog: {ex.Message}";
            loading = false;
        }
    }

    private async Task LoadProducts()
    {
        loading = true;
        errorMessage = null;

        try
        {
            var result = await ProductService.SearchAsync(currentFilter, currentSort, currentPage, pageSize);
            products = result.Items;
            totalCount = result.TotalCount;
            totalPages = (int)Math.Ceiling((double)result.TotalCount / pageSize);
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load products: {ex.Message}";
            products = [];
        }
        finally
        {
            loading = false;
        }
    }

    private async Task HandleFilterApplied(CatalogSidebar.ProductFilterState filterState)
    {
        currentFilter = new ProductFilter(
            filterState.Categories,
            filterState.MinPrice,
            filterState.MaxPrice,
            filterState.InStockOnly);
        currentPage = 1;
        await LoadProducts();
    }

    private async Task HandleFilterCleared()
    {
        currentFilter = new ProductFilter(null, null, null, false);
        currentPage = 1;
        await LoadProducts();
    }

    private async Task HandleSortChanged(string sort)
    {
        currentSort = sort;
        currentPage = 1;
        await LoadProducts();
    }

    private async Task HandlePageChanged(int page)
    {
        currentPage = page;
        await LoadProducts();
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private Task HandleAddToCart(Product product)
    {
        // Placeholder for add-to-cart logic
        return Task.CompletedTask;
    }
}
"}

